softmaxGradAVX512_loop:
	VMOVUPS (CX), Z1
	VSUBPS  Z0, Z1, Z1
	VMULPS  (AX), Z1, Z1
	VMOVUPS Z1, (AX)
	ADDQ    $0x00000040, AX
