// func dot4AVX512(x *float32, y *float32, stride int, n int, out *float32)
// Requires: AVX, AVX512DQ, AVX512F, SSE
TEXT ·dot4AVX512(SB), NOSPLIT, $0-40
	MOVQ   x+0(FP), AX
	MOVQ   stride+16(FP), CX
	MOVQ   n+24(FP), DX
	SHLQ   $0x02, CX
	MOVQ   y+8(FP), BX
	LEAQ   (BX)(CX*1), SI
	LEAQ   (SI)(CX*1), DI
	LEAQ   (DI)(CX*1), CX
	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
	VXORPS Z2, Z2, Z2
	VXORPS Z3, Z3, Z3
	VXORPS Z4, Z4, Z4
	VXORPS Z5, Z5, Z5
	VXORPS Z6, Z6, Z6
	VXORPS Z7, Z7, Z7
	CMPQ   DX, $0x00000020
	JL     dot4AVX512_tail

dot4AVX512_wide:
	VMOVUPS     (AX), Z8
	VMOVUPS     64(AX), Z9
	VFMADD231PS (BX), Z8, Z0
	VFMADD231PS 64(BX), Z9, Z1
	ADDQ        $0x00000080, BX
	VFMADD231PS (SI), Z8, Z2
	VFMADD231PS 64(SI), Z9, Z3
	ADDQ        $0x00000080, SI
	VFMADD231PS (DI), Z8, Z4
	VFMADD231PS 64(DI), Z9, Z5
	ADDQ        $0x00000080, DI
	VFMADD231PS (CX), Z8, Z6
	VFMADD231PS 64(CX), Z9, Z7
	ADDQ        $0x00000080, CX
	ADDQ        $0x00000080, AX
	SUBQ        $0x00000020, DX
	CMPQ        DX, $0x00000020
	JGE         dot4AVX512_wide

dot4AVX512_tail:
	TESTQ       DX, DX
	JZ          dot4AVX512_done
	VMOVUPS     (AX), Z8
	VFMADD231PS (BX), Z8, Z0
	VFMADD231PS (SI), Z8, Z2
	VFMADD231PS (DI), Z8, Z4
	VFMADD231PS (CX), Z8, Z6

dot4AVX512_done:
	MOVQ          out+32(FP), AX
	VADDPS        Z1, Z0, Z0
	VEXTRACTF64X4 $0x01, Z0, Y1
	VADDPS        Y1, Y0, Y0
	VEXTRACTF128  $0x01, Y0, X1
	VADDPS        X1, X0, X0
	VPERMILPS     $0x4e, X0, X1
	VADDPS        X1, X0, X0
	VPERMILPS     $0xb1, X0, X1
	VADDPS        X1, X0, X0
	MOVSS         X0, (AX)
	VADDPS        Z3, Z2, Z2
	VEXTRACTF64X4 $0x01, Z2, Y0
	VADDPS        Y0, Y2, Y2
	VEXTRACTF128  $0x01, Y2, X0
	VADDPS        X0, X2, X2
	VPERMILPS     $0x4e, X2, X0
	VADDPS        X0, X2, X2
	VPERMILPS     $0xb1, X2, X0
	VADDPS        X0, X2, X2
	MOVSS         X2, 4(AX)
	VADDPS        Z5, Z4, Z4
	VEXTRACTF64X4 $0x01, Z4, Y0
	VADDPS        Y0, Y4, Y4
	VEXTRACTF128  $0x01, Y4, X0
	VADDPS        X0, X4, X4
	VPERMILPS     $0x4e, X4, X0
	VADDPS        X0, X4, X4
	VPERMILPS     $0xb1, X4, X0
	VADDPS        X0, X4, X4
	MOVSS         X4, 8(AX)
	VADDPS        Z7, Z6, Z6
	VEXTRACTF64X4 $0x01, Z6, Y0
	VADDPS        Y0, Y6, Y6
	VEXTRACTF128  $0x01, Y6, X0
	VADDPS        X0, X6, X6
	VPERMILPS     $0x4e, X6, X0
	VADDPS        X0, X6, X6
	VPERMILPS     $0xb1, X6, X0
	VADDPS        X0, X6, X6
	MOVSS         X6, 12(AX)
	VZEROUPPER
	RET

// func exp2AVX512(dst *float32, src *float32, n int)
// Requires: AVX, AVX512F
TEXT ·exp2AVX512(SB), NOSPLIT, $0-24
	MOVQ  dst+0(FP), AX
	MOVQ  src+8(FP), CX
	MOVQ  n+16(FP), DX
	TESTQ DX, DX
	JZ    exp2AVX512_done

exp2AVX512_loop:
	VMOVUPS     (CX), Z0
	VMAXPS      exp_exp2lo<>+0(SB), Z0, Z0
	VMINPS      exp_exp2hi<>+0(SB), Z0, Z0
	VCVTPS2DQ   Z0, Z1
	VCVTDQ2PS   Z1, Z2
	VSUBPS      Z2, Z0, Z0
	VMOVUPS     exp_q0<>+0(SB), Z2
	VFMADD213PS exp_q1<>+0(SB), Z0, Z2
	VFMADD213PS exp_q2<>+0(SB), Z0, Z2
	VFMADD213PS exp_q3<>+0(SB), Z0, Z2
	VFMADD213PS exp_q4<>+0(SB), Z0, Z2
	VFMADD213PS exp_q5<>+0(SB), Z0, Z2
	VFMADD213PS exp_one<>+0(SB), Z0, Z2
	VPADDD      exp_bias<>+0(SB), Z1, Z1
	VPSLLD      $0x17, Z1, Z1
	VMULPS      Z1, Z2, Z2
	VMOVUPS     Z2, (AX)
	ADDQ        $0x00000040, AX
	ADDQ        $0x00000040, CX
	SUBQ        $0x00000010, DX
	JNZ         exp2AVX512_loop

exp2AVX512_done:
