// func expShiftAVX2(x *float32, n int, shift float32) float32
// Requires: AVX, AVX2, FMA3, SSE
TEXT ·expShiftAVX2(SB), NOSPLIT, $0-28
	MOVQ         x+0(FP), AX
	MOVQ         n+8(FP), CX
	MOVSS        shift+16(FP), X0
	VBROADCASTSS X0, Y0
	VXORPS       Y1, Y1, Y1
	TESTQ        CX, CX
	JZ           expShiftAVX2_done

expShiftAVX2_loop:
	VMOVUPS      (AX), Y2
	VSUBPS       Y0, Y2, Y2
	VCMPPS       $0x01, exp_lowest<>+0(SB), Y2, Y3
	VMAXPS       exp_lowest<>+0(SB), Y2, Y2
	VMINPS       exp_highest<>+0(SB), Y2, Y2
	VMULPS       exp_log2e<>+0(SB), Y2, Y5
	VCVTPS2DQ    Y5, Y4
	VCVTDQ2PS    Y4, Y5
	VFNMADD231PS exp_ln2hi<>+0(SB), Y5, Y2
	VFNMADD231PS exp_ln2lo<>+0(SB), Y5, Y2
	VMOVUPS      exp_p0<>+0(SB), Y5
	VFMADD213PS  exp_p1<>+0(SB), Y2, Y5
	VFMADD213PS  exp_p2<>+0(SB), Y2, Y5
	VFMADD213PS  exp_p3<>+0(SB), Y2, Y5
	VFMADD213PS  exp_p4<>+0(SB), Y2, Y5
	VFMADD213PS  exp_p5<>+0(SB), Y2, Y5
	VMULPS       Y2, Y2, Y6
	VFMADD213PS  Y2, Y6, Y5
	VADDPS       exp_one<>+0(SB), Y5, Y5
	VPADDD       exp_bias<>+0(SB), Y4, Y4
	VPSLLD       $0x17, Y4, Y4
	VMULPS       Y4, Y5, Y5
	VANDNPS      Y5, Y3, Y5
	VMOVUPS      Y5, (AX)
	VADDPS       Y5, Y1, Y1
	ADDQ         $0x00000020, AX
	SUBQ         $0x00000008, CX
	JNZ          expShiftAVX2_loop

expShiftAVX2_done:
	VEXTRACTF128 $0x01, Y1, X0
	VADDPS       X0, X1, X1
	VPERMILPS    $0x4e, X1, X0
	VADDPS       X0, X1, X1
	VPERMILPS    $0xb1, X1, X0
	VADDPS       X0, X1, X1
	MOVSS        X1, ret+24(FP)
	VZEROUPPER
	RET

