// Requires: AVX, AVX2, SSE
TEXT ·softmaxGradAVX2(SB), NOSPLIT, $0-28
	MOVQ         p+0(FP), AX
	MOVQ         dp+8(FP), CX
	MOVQ         n+16(FP), DX
	MOVSS        d+24(FP), X0
	VBROADCASTSS X0, Y0
	TESTQ        DX, DX
	JZ           softmaxGradAVX2_done

softmaxGradAVX2_loop:
	VMOVUPS (CX), Y1
	VSUBPS  Y0, Y1, Y1
	VMULPS  (AX), Y1, Y1
	VMOVUPS Y1, (AX)
	ADDQ    $0x00000020, AX
	ADDQ    $0x00000020, CX
	SUBQ    $0x00000008, DX
	JNZ     softmaxGradAVX2_loop

softmaxGradAVX2_done:
	VZEROUPPER
	RET

// func dot4AVX2(x *float32, y *float32, stride int, n int, out *float32)
// Requires: AVX, FMA3, SSE
TEXT ·dot4AVX2(SB), NOSPLIT, $0-40
	MOVQ   x+0(FP), AX
	MOVQ   stride+16(FP), CX
	MOVQ   n+24(FP), DX
	SHLQ   $0x02, CX
	MOVQ   y+8(FP), BX
	LEAQ   (BX)(CX*1), SI
	LEAQ   (SI)(CX*1), DI
	LEAQ   (DI)(CX*1), CX
	VXORPS Y0, Y0, Y0
	VXORPS Y1, Y1, Y1
	VXORPS Y2, Y2, Y2
	VXORPS Y3, Y3, Y3
	VXORPS Y4, Y4, Y4
	VXORPS Y5, Y5, Y5
	VXORPS Y6, Y6, Y6
	VXORPS Y7, Y7, Y7
	CMPQ   DX, $0x00000010
	JL     dot4AVX2_tail

dot4AVX2_wide:
	VMOVUPS     (AX), Y8
	VMOVUPS     32(AX), Y9
	VFMADD231PS (BX), Y8, Y0
	VFMADD231PS 32(BX), Y9, Y1
	ADDQ        $0x00000040, BX
	VFMADD231PS (SI), Y8, Y2
	VFMADD231PS 32(SI), Y9, Y3
	ADDQ        $0x00000040, SI
	VFMADD231PS (DI), Y8, Y4
	VFMADD231PS 32(DI), Y9, Y5
	ADDQ        $0x00000040, DI
	VFMADD231PS (CX), Y8, Y6
	VFMADD231PS 32(CX), Y9, Y7
	ADDQ        $0x00000040, CX
	ADDQ        $0x00000040, AX
	SUBQ        $0x00000010, DX
	CMPQ        DX, $0x00000010
	JGE         dot4AVX2_wide

dot4AVX2_tail:
	TESTQ       DX, DX
	JZ          dot4AVX2_done
	VMOVUPS     (AX), Y8
	VFMADD231PS (BX), Y8, Y0
	VFMADD231PS (SI), Y8, Y2
	VFMADD231PS (DI), Y8, Y4
	VFMADD231PS (CX), Y8, Y6

dot4AVX2_done:
	MOVQ         out+32(FP), AX
	VADDPS       Y1, Y0, Y0
	VEXTRACTF128 $0x01, Y0, X1
	VADDPS       X1, X0, X0
	VPERMILPS    $0x4e, X0, X1
	VADDPS       X1, X0, X0
	VPERMILPS    $0xb1, X0, X1
	VADDPS       X1, X0, X0
	MOVSS        X0, (AX)
	VADDPS       Y3, Y2, Y2
	VEXTRACTF128 $0x01, Y2, X0
	VADDPS       X0, X2, X2
	VPERMILPS    $0x4e, X2, X0
	VADDPS       X0, X2, X2
	VPERMILPS    $0xb1, X2, X0
	VADDPS       X0, X2, X2
	MOVSS        X2, 4(AX)
	VADDPS       Y5, Y4, Y4
	VEXTRACTF128 $0x01, Y4, X0
	VADDPS       X0, X4, X4
	VPERMILPS    $0x4e, X4, X0
	VADDPS       X0, X4, X4
	VPERMILPS    $0xb1, X4, X0
	VADDPS       X0, X4, X4
	MOVSS        X4, 8(AX)
	VADDPS       Y7, Y6, Y6
	VEXTRACTF128 $0x01, Y6, X0
	VADDPS       X0, X6, X6
	VPERMILPS    $0x4e, X6, X0
	VADDPS       X0, X6, X6
	VPERMILPS    $0xb1, X6, X0
	VADDPS       X0, X6, X6
	MOVSS        X6, 12(AX)
	VZEROUPPER
	RET

// func exp2AVX2(dst *float32, src *float32, n int)
// Requires: AVX, AVX2, FMA3
TEXT ·exp2AVX2(SB), NOSPLIT, $0-24
	MOVQ  dst+0(FP), AX
	MOVQ  src+8(FP), CX
	MOVQ  n+16(FP), DX
	TESTQ DX, DX
	JZ    exp2AVX2_done

exp2AVX2_loop:
	VMOVUPS     (CX), Y0
	VMAXPS      exp_exp2lo<>+0(SB), Y0, Y0
	VMINPS      exp_exp2hi<>+0(SB), Y0, Y0
	VCVTPS2DQ   Y0, Y1
	VCVTDQ2PS   Y1, Y2
	VSUBPS      Y2, Y0, Y0
	VMOVUPS     exp_q0<>+0(SB), Y2
	VFMADD213PS exp_q1<>+0(SB), Y0, Y2
	VFMADD213PS exp_q2<>+0(SB), Y0, Y2
	VFMADD213PS exp_q3<>+0(SB), Y0, Y2
	VFMADD213PS exp_q4<>+0(SB), Y0, Y2
	VFMADD213PS exp_q5<>+0(SB), Y0, Y2
	VFMADD213PS exp_one<>+0(SB), Y0, Y2
	VPADDD      exp_bias<>+0(SB), Y1, Y1
	VPSLLD      $0x17, Y1, Y1
	VMULPS      Y1, Y2, Y2
	VMOVUPS     Y2, (AX)
	ADDQ        $0x00000020, AX
	ADDQ        $0x00000020, CX
	SUBQ        $0x00000008, DX
	JNZ         exp2AVX2_loop

exp2AVX2_done:
	VZEROUPPER
	RET

